export interface ConnectorConfig {
  /** Zendesk subdomain (e.g., 'mycompany' for mycompany.zendesk.com) */
  zendeskSubdomain: string
  /** Zendesk API access token (Bearer token) */
  zendeskAccessToken: string
  /** Intercom webhook secret for signature verification (optional, for future use) */
  intercomWebhookSecret?: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface IntercomWebhookPayload {
  type: string
  topic: string
  data: {
    item: {
      type: string
      id: string
      url: string
    }
  }
}

export interface HandleResult {
  ticketId: number
  ticketUrl: string
}

async function verifySignature(
  payload: string,
  signature: string | null,
  secret: string | undefined,
): Promise<void> {
  if (!secret) return
  if (!signature) throw new Error('Missing X-Hub-Signature header')
  const encoder = new TextEncoder()
  const key = await crypto.subtle.importKey('raw', encoder.encode(secret), { name: 'HMAC', hash: 'SHA-1' }, false, ['sign'])
  const expected = await crypto.subtle.sign('HMAC', key, encoder.encode(payload))
  const expectedHex = Array.from(new Uint8Array(expected))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('')
  if (signature !== expectedHex) throw new Error('Invalid webhook signature')
}

export async function handle(
  payload: IntercomWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (!payload.data?.item?.id) throw new Error('Missing required field: data.item.id')
  if (!payload.data?.item?.url) throw new Error('Missing required field: data.item.url')
  if (payload.topic !== 'conversation.tag.created') {
    throw new Error(`Unsupported topic: ${payload.topic}. Expected 'conversation.tag.created'`)
  }

  const conversationId = payload.data.item.id
  const conversationUrl = payload.data.item.url

  // Build Zendesk ticket payload
  const ticketPayload = {
    ticket: {
      subject: conversationUrl,
      description: `Conversation ID: ${conversationId}`,
    },
  }

  const url = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets.json`
  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.zendeskAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(ticketPayload),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`Zendesk API error (${response.status} ${response.statusText}) at ${url}: ${text}`)
  }

  const result = (await response.json()) as { ticket: { id: number; url: string } }
  return { ticketId: result.ticket.id, ticketUrl: result.ticket.url }
}

