    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '12345',
          url: 'https://app.intercom.com/a/apps/<app_id>/inbox/conversations/12345',
        },
      },
    }
    const result = await handle(payload, { ...baseConfig, fetch })
    expect(result.ticketId).toBe(12345)
  })

  it('throws when data.item.id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      type: 'notification_event',
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', url: 'https://example.com' } },
    } as unknown as IntercomWebhookPayload
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: data.item.id')
  })

  it('throws when data.item.url is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      type: 'notification_event',
      topic: 'conversation.tag.created',
      data: { item: { type: 'conversation', id: '123' } },
    } as unknown as IntercomWebhookPayload
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: data.item.url')
  })

  it('throws when topic is not conversation.tag.created', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation.tag.removed',
      data: {
        item: {
          type: 'conversation',
          id: '12345',
          url: 'https://app.intercom.com/a/apps/<app_id>/inbox/conversations/12345',
        },
      },
    }
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow("Unsupported topic: conversation.tag.removed")
  })

  it('throws on non-2xx response from Zendesk', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '12345',
          url: 'https://app.intercom.com/a/apps/<app_id>/inbox/conversations/12345',
        },
      },
    }
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
